export function composedGrants(provider, resources, constraints) {
    const expand = async (grants, input) => Promise.all(grants
        .flatMap((grant) => resources.expand(grant))
        .map(async (grant) => {
        if (!grant.origin?.scopeKey)
            return grant;
        const branchConstraints = await constraints.resolve({
            ...input,
            ...grant.origin,
        });
        return {
            ...grant,
            policy: {
                ...grant.policy,
                type: grant.policy?.type ?? 'database',
                branchConstraints,
            },
        };
    }));
    return {
        resolveAll: async (input) => expand(await provider.resolveAll(input), input),
        resolve: async (input) => {
            const direct = await provider.resolve(input);
            const business = resources.definitionsList().length
                ? (await provider.resolveAll(input)).filter((grant) => grant.resource.type === 'resource')
                : [];
            const expanded = (await expand(business, input)).filter((grant) => grant.resource.type !== 'resource');
            // Validate business policies even when only checking the feature itself.
            if (input.resource.type === 'resource')
                direct.forEach((grant) => resources.expand(grant));
            return [...direct, ...expanded].filter((grant) => grant.resource.type === input.resource.type &&
                (grant.resource.id === '*' ||
                    grant.resource.id === input.resource.id) &&
                grant.action === input.action);
        },
        unrestricted: provider.unrestricted?.bind(provider),
        onChange: provider.onChange?.bind(provider),
        scope: (identity) => composedGrants(provider.scope?.(identity) ?? provider, resources, constraints),
    };

