scope(identity) {
    const cache = new Map();
    const resolvers = [...this.resolvers.values()].map((resolver) => resolver.scope?.(identity) ?? resolver);
    return {
        resolve: (input) => {
            const key = `${input.resource.type}\u0000${input.resource.id}\u0000${input.action}\u0000${input.scopeKey ?? ''}`;
            let result = cache.get(key);
            if (!result) {
                result = Promise.all(resolvers.map((resolver) => resolver.resolve({
                    ...input,
                    principal: identity.principal,
                    subjects: identity.subjects,
                }))).then((results) => results.flat());
                cache.set(key, result);
            }
            return result;
        },
    };
}

